{
  "name": "串口CAN总线通信组件",
  "name_en": "Serial CAN Bus Interface",
  "manufacturer": "",
  "description": "一个非物理的软件通信组件，用于通过串口设备进行基础 CAN 总线消息收发与连接管理，常用于实验系统中连接、转发或管理基于 CAN 的仪器通信。",
  "description_en": "A non-physical software communication component for basic CAN bus messaging and connection management over a serial device, typically used in laboratory systems to connect, relay, or manage communication with CAN-based instruments.",
  "actions": [
    {
      "action_name": "auto-shutdown",
      "description": "关闭串口通信接口。",
      "description_en": "Close the serial communication interface."
    },
    {
      "action_name": "auto-send",
      "description": "通过串口链路发送一条 CAN 消息。",
      "description_en": "Send a CAN message over the serial link."
    },
    {
      "action_name": "auto-fileno",
      "description": "返回底层串口接口的文件描述符。",
      "description_en": "Return the file descriptor of the underlying serial interface."
    }
  ],
  "tag_hints": [
    "CAN bus communication",
    "serial interface",
    "serial-to-CAN",
    "message transport",
    "instrument connectivity",
    "file descriptor access"
  ]
}

